const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year = 2003;
  const startDate = `${year}-01-01`;
  const endDate = `${year}-12-31`;

  // Define geometries for the three locations.
  // Queensland is large, so a representative polygon is used.
  const queensland = ee.Geometry.Polygon([[
    [138.12, -29.04], [153.63, -29.04], [153.63, -10.05], [138.12, -10.05], [138.12, -29.04]
  ]]);
  // Lut Desert, Iran - A known hot spot.
  const lutDesert = ee.Geometry.Point([59.07, 30.56]);
  // El Azizia, Libya - historically recorded one of the highest temperatures.
  const elAzizia = ee.Geometry.Point([13.02, 32.53]);

  // 2. Data Acquisition
  const modisLST = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .select('LST_Day_1km');

  // Check if the collection is empty. Highly unlikely for MODIS, but good practice.
  if (modisLST.size().getInfo() === 0) {
    console.log('Evidence: No MODIS images found for 2003.');
    console.log('A: No');
    console.log('B: No');
    console.log('C1: Empty Collection');
    return;
  }

  // 3. Processing
  // Function to apply scale factor, convert K to C, and mask low-quality pixels.
  // According to MODIS QA, bits 0-1 = '00' means "LST produced, good quality".
  const processLST = function(image) {
    const quality = image.select('QC_Day');
    const goodQuality = quality.bitwiseAnd(0b11).eq(0); // Check bits 0-1
    return image.select('LST_Day_1km')
      .updateMask(goodQuality)
      .multiply(0.02)    // Apply scale factor
      .subtract(273.15); // Convert Kelvin to Celsius
  };

  const lstCelsius = modisLST.map(processLST);

  // Create a single image representing the maximum temperature for the whole year.
  const maxTemp2003 = lstCelsius.max();

  // 4. Calculation
  // Function to get max temperature and pixel count for a given geometry.
  const getStats = (geometry) => {
    const reducer = ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    });

    const stats = maxTemp2003.reduceRegion({
      reducer: reducer,
      geometry: geometry,
      scale: 1000, // MODIS native resolution is 1km
      maxPixels: 1e12
    });
    return stats.getInfo();
  };

  const queenslandStats = getStats(queensland);
  const lutDesertStats = getStats(lutDesert.buffer(5000)); // Buffer point for robust stat
  const elAziziaStats = getStats(elAzizia.buffer(5000));   // Buffer point for robust stat

  // 5. Validation & Final Answer
  const qldMax = queenslandStats.LST_Day_1km_max;
  const lutMax = lutDesertStats.LST_Day_1km_max;
  const aziziaMax = elAziziaStats.LST_Day_1km_max;

  const qldPixels = queenslandStats.LST_Day_1km_count;
  const lutPixels = lutDesertStats.LST_Day_1km_count;
  const aziziaPixels = elAziziaStats.LST_Day_1km_count;

  // Check for C2: No Valid Pixels
  if (!qldPixels || !lutPixels || !aziziaPixels) {
      console.log(`Evidence: Pixel counts after masking - QLD: ${qldPixels}, Lut: ${lutPixels}, El Azizia: ${aziziaPixels}`);
      console.log('Reason: At least one region has no valid pixels after cloud/quality masking.');
      console.log('C2: No Valid Pixels');
      return;
  }

  // Check for C3: Calculation Failure
  if (qldMax === null || lutMax === null || aziziaMax === null) {
      console.log(`Evidence: Max temps - QLD: ${qldMax}, Lut: ${lutMax}, El Azizia: ${aziziaMax}`);
      console.log('Reason: Calculation resulted in a null value.');
      console.log('C3: Calculation Failure');
      return;
  }

  console.log(`Max Temp Queensland (°C): ${qldMax.toFixed(2)} (Pixels: ${qldPixels})`);
  console.log(`Max Temp Lut Desert (°C): ${lutMax.toFixed(2)} (Pixels: ${lutPixels})`);
  console.log(`Max Temp El Azizia (°C): ${aziziaMax.toFixed(2)} (Pixels: ${aziziaPixels})`);

  if (qldMax > lutMax && qldMax > aziziaMax) {
      console.log('A: Yes');
  } else {
      console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
});
